import { Resend } from 'resend';
import axios from 'axios';
import dotenv from 'dotenv';
import type { MonitoredSite, AlertChannel } from '@pingwatch/shared';

dotenv.config();

const RESEND_API_KEY = process.env.RESEND_API_KEY || '';
const FROM_EMAIL = process.env.FROM_EMAIL || 'alerts@pingwatch.app';

let resendClient: Resend | null = null;
if (RESEND_API_KEY && !RESEND_API_KEY.includes('placeholder')) {
  resendClient = new Resend(RESEND_API_KEY);
}

export interface NotificationPayload {
  site: MonitoredSite;
  type: 'DOWN' | 'UP';
  timestamp: string;
  errorMessage?: string | null;
  downtimeDuration?: string | null;
}

export async function sendAlertNotification(
  channel: AlertChannel,
  payload: NotificationPayload
): Promise<void> {
  const { site, type, timestamp, errorMessage, downtimeDuration } = payload;

  try {
    if (channel.channel_type === 'email') {
      const recipient = channel.config?.email;
      if (!recipient) {
        console.warn(`[Notifier] Missing email in alert channel ${channel.id}`);
        return;
      }

      const isDown = type === 'DOWN';
      const subject = isDown
        ? `🔴 [${site.name}] is DOWN`
        : `🟢 [${site.name}] is back UP`;

      const textBody = isDown
        ? `Alert: ${site.name} is currently DOWN.\n\n` +
          `URL: ${site.url}\n` +
          `Time Detected: ${timestamp}\n` +
          `Error Details: ${errorMessage || 'No response / Timeout'}\n\n` +
          `PingWatch will continue monitoring and notify you once it recovers.`
        : `Recovery: ${site.name} is back UP and responding normally.\n\n` +
          `URL: ${site.url}\n` +
          `Time Recovered: ${timestamp}\n` +
          `Downtime Duration: ${downtimeDuration || 'Unknown'}\n\n` +
          `Monitored by PingWatch.`;

      const htmlBody = `
        <div style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; max-width: 600px; margin: 0 auto; padding: 24px; background-color: #0D1117; color: #FFFFFF; border-radius: 8px;">
          <div style="border-bottom: 1px solid #30363D; padding-bottom: 16px; margin-bottom: 20px;">
            <span style="font-size: 14px; font-weight: 700; color: #8B949E; text-transform: uppercase; letter-spacing: 0.05em;">PingWatch Alert</span>
            <h1 style="font-size: 22px; margin: 8px 0 0 0; color: ${isDown ? '#FF4D4F' : '#00FF87'};">
              ${subject}
            </h1>
          </div>

          <table style="width: 100%; border-collapse: collapse; margin-bottom: 24px;">
            <tr>
              <td style="padding: 8px 0; color: #8B949E; font-size: 14px; width: 140px;">Monitored Site:</td>
              <td style="padding: 8px 0; font-size: 14px; font-weight: 600;">${site.name}</td>
            </tr>
            <tr>
              <td style="padding: 8px 0; color: #8B949E; font-size: 14px;">Target URL:</td>
              <td style="padding: 8px 0; font-family: monospace; font-size: 13px; color: #58A6FF;">${site.url}</td>
            </tr>
            <tr>
              <td style="padding: 8px 0; color: #8B949E; font-size: 14px;">Timestamp:</td>
              <td style="padding: 8px 0; font-size: 14px;">${new Date(timestamp).toUTCString()}</td>
            </tr>
            ${isDown && errorMessage ? `
            <tr>
              <td style="padding: 8px 0; color: #8B949E; font-size: 14px;">Root Cause:</td>
              <td style="padding: 8px 0; font-size: 14px; color: #FF7B72; font-family: monospace;">${errorMessage}</td>
            </tr>
            ` : ''}
            ${!isDown && downtimeDuration ? `
            <tr>
              <td style="padding: 8px 0; color: #8B949E; font-size: 14px;">Total Downtime:</td>
              <td style="padding: 8px 0; font-size: 14px; color: #00FF87; font-weight: 600;">${downtimeDuration}</td>
            </tr>
            ` : ''}
          </table>

          <div style="border-top: 1px solid #30363D; padding-top: 16px; font-size: 12px; color: #8B949E; text-align: center;">
            PingWatch Uptime Monitoring System &bull; Instant SaaS alerts
          </div>
        </div>
      `;

      if (resendClient) {
        const { error } = await resendClient.emails.send({
          from: FROM_EMAIL,
          to: recipient,
          subject,
          text: textBody,
          html: htmlBody,
        });

        if (error) {
          console.error(`[Notifier] Resend email delivery failed to ${recipient}:`, error);
        } else {
          console.log(`[Notifier] Resend email successfully sent to ${recipient} for site ${site.name} (${type})`);
        }
      } else {
        console.log(`[Notifier] [DRY RUN - No RESEND_API_KEY] Would send email to ${recipient}: "${subject}"`);
      }
    } else if (channel.channel_type === 'webhook') {
      const webhookUrl = channel.config?.url;
      if (!webhookUrl) {
        console.warn(`[Notifier] Missing webhook url in channel ${channel.id}`);
        return;
      }

      await axios.post(
        webhookUrl,
        {
          event: type === 'DOWN' ? 'site.down' : 'site.up',
          timestamp,
          site: {
            id: site.id,
            name: site.name,
            url: site.url,
          },
          details: {
            error_message: errorMessage || null,
            downtime_duration: downtimeDuration || null,
          },
        },
        {
          timeout: 5000,
          headers: { 'Content-Type': 'application/json' },
        }
      );
      console.log(`[Notifier] Webhook triggered for ${webhookUrl} (${type})`);
    }
  } catch (err: any) {
    console.error(`[Notifier] Failed to dispatch notification for channel ${channel.id}:`, err.message);
  }
}
